import { test } from '@playwright/test'

test('debug reorder', async ({ page }) => {
  await page.goto('/')
  await page.evaluate(() => localStorage.setItem('kanban.board.v1', JSON.stringify({
    cards: { a: { id: 'a', title: 'AAA', priority: 'low' }, b: { id: 'b', title: 'BBB', priority: 'low' }, c: { id: 'c', title: 'CCC', priority: 'low' } },
    columns: { todo: ['a', 'b', 'c'], doing: [], done: [] },
  })))
  await page.reload()
  const cards = page.getByTestId('card')
  const boxes = await Promise.all([0, 1, 2].map(async (i) => (await cards.nth(i).boundingBox())!))
  console.log('boxes', JSON.stringify(boxes))
  const a = boxes[0]
  const c = boxes[2]
  for (const targetY of [c.y + c.height / 2, c.y + c.height - 4, c.y + 10]) {
    await page.goto('/')
    await page.mouse.move(a.x + a.width / 2, a.y + 12)
    await page.mouse.down()
    await page.mouse.move(a.x + a.width / 2 + 10, a.y + 25, { steps: 3 })
    await page.mouse.move(a.x + a.width / 2, targetY, { steps: 15 })
    await page.screenshot({ path: `shots/debug-${Math.round(targetY)}.png` })
    await page.mouse.up()
    await page.waitForTimeout(400)
    console.log(targetY, await cards.allInnerTexts().then((t) => t.map((s) => s.slice(0, 3))))
    await page.evaluate(() => localStorage.setItem('kanban.board.v1', JSON.stringify({
      cards: { a: { id: 'a', title: 'AAA', priority: 'low' }, b: { id: 'b', title: 'BBB', priority: 'low' }, c: { id: 'c', title: 'CCC', priority: 'low' } },
      columns: { todo: ['a', 'b', 'c'], doing: [], done: [] },
    })))
  }
})

